 4 | export function createMonitorClient(options: { baseUrl: string; token: string; fetch?: typeof fetch; timeoutMs?: number }) {
 5 |   const base = options.baseUrl.replace(/\/$/, '');
 6 |   const transport = options.fetch ?? fetch;
 7 |   async function get<T>(path: string): Promise<T> {
 8 |     const response = await transport(`${base}/v1/monitor${path}`, {
 9 |       headers: { authorization: `Bearer ${options.token}` }, signal: AbortSignal.timeout(options.timeoutMs ?? 10000),
10 |       redirect: 'error', cache: 'no-store',
11 |     });
12 |     if (!response.ok) throw Object.assign(new Error(`Node monitor returned HTTP ${response.status}`), { status: response.status });
13 |     return await response.json() as T;
14 |   }
15 |   const id = (value: string) => {
16 |     if (!/^[a-f0-9]{64}$/.test(value)) throw new TypeError('A monitor observation ID is required');
17 |     return value;
18 |   };
19 |   return {
20 |     node: () => get<NodeSnapshot>('/node'),
21 |     tasks: (query: { status?: TaskState; q?: string; offset?: number; limit?: number } = {}) =>
22 |       get<TaskPage>(`/tasks?${new URLSearchParams(Object.entries(query).map(([key, value]) => [key, String(value)]))}`),
23 |     task: (taskId: string) => get<{ schemaVersion: string; task: TaskDetail }>(`/tasks/${id(taskId)}`),
24 |     events: (taskId: string, after = 0, limit = 100) =>
25 |       get<{ schemaVersion: string; items: MonitorEvent[]; nextCursor: number; hasMore: boolean; truncated: boolean; earliestCursor: number | null }>(`/tasks/${id(taskId)}/events?after=${after}&limit=${limit}`),
26 |     models: (taskId: string) => get<{ schemaVersion: string; models: ModelCall[] }>(`/tasks/${id(taskId)}/models`),
27 |     skills: (taskId: string) => get<{ schemaVersion: string; skills: TaskDetail['skills'] }>(`/tasks/${id(taskId)}/skills`),
28 |     codes: (taskId: string) => get<{ schemaVersion: string; codes: CodeVersion[] }>(`/tasks/${id(taskId)}/codes`),
29 |     python: (taskId: string) => get<unknown>(`/tasks/${id(taskId)}/python`),
30 |     code: (taskId: string, codeId: string) => get<CodeVersion>(`/tasks/${id(taskId)}/codes/${id(codeId)}`),
31 |   };
32 | }
